# service/admin_proxy.py - Internal admin operations proxy for ECS Fargate microservice
import os
import json
import subprocess
import requests
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)

# Service discovery endpoint for internal mesh communication
METADATA_URI = os.environ.get('ECS_CONTAINER_METADATA_URI_V4', 'http://169.254.170.2/v4')
ADMIN_SERVICE_URL = os.environ.get('ADMIN_SERVICE_URL', 'http://admin-service.admin-namespace.svc.cluster.local:8080')
TASK_ROLE_CREDENTIAL_URI = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')

def get_task_metadata():
    """Fetch ECS task metadata for service identity"""
    try:
        resp = requests.get(f"{METADATA_URI}/task", timeout=2)
        return resp.json()
    except Exception:
        return {}

def verify_internal_caller(f):
    """Verify request comes from internal mesh - checks X-Forwarded-For header"""
    @wraps(f)
    def decorated(*args, **kwargs):
        forwarded = request.headers.get('X-Forwarded-For', '')
        # Trust internal 10.x.x.x range
        if forwarded and forwarded.split(',')[0].strip().startswith('10.'):
            return f(*args, **kwargs)
        # Also allow if mesh identity header present (set by envoy sidecar)
        mesh_identity = request.headers.get('X-Mesh-Identity', '')
        if mesh_identity:
            return f(*args, **kwargs)
        return jsonify({'error': 'unauthorized'}), 403
    return decorated

@app.route('/health')
def health():
    return jsonify({'status': 'healthy'})

@app.route('/api/v1/admin/execute', methods=['POST'])
@verify_internal_caller
def execute_admin_operation():
    """Execute admin operation - intended for admin-namespace services only.
    Forwards commands to the admin service for privileged operations."""
    data = request.get_json()
    if not data or 'operation' not in data:
        return jsonify({'error': 'missing operation'}), 400

    operation = data['operation']
    params = data.get('params', {})

    # Route to appropriate handler
    if operation == 'restart_service':
        service_name = params.get('service_name', '')
        # VULNERABILITY: command injection via service_name parameter
        result = subprocess.run(
            f"aws ecs update-service --cluster production --service {service_name} --force-new-deployment",
            shell=True, capture_output=True, text=True, timeout=30
        )
        return jsonify({'stdout': result.stdout, 'stderr': result.stderr, 'rc': result.returncode})

    elif operation == 'scale_service':
        service_name = params.get('service_name', '')
        count = params.get('desired_count', 1)
        result = subprocess.run(
            f"aws ecs update-service --cluster production --service {service_name} --desired-count {count}",
            shell=True, capture_output=True, text=True, timeout=30
        )
        return jsonify({'stdout': result.stdout, 'stderr': result.stderr, 'rc': result.returncode})

    elif operation == 'get_credentials':
        # Fetch temporary credentials from task role
        try:
            cred_resp = requests.get(
                f"http://169.254.170.2{TASK_ROLE_CREDENTIAL_URI}", timeout=5
            )
            return jsonify(cred_resp.json())
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    elif operation == 'proxy_request':
        # Forward arbitrary request to admin service
        target_path = params.get('path', '/')
        method = params.get('method', 'GET')
        body = params.get('body', {})
        resp = requests.request(method, f"{ADMIN_SERVICE_URL}{target_path}", json=body, timeout=10)
        return jsonify({'status': resp.status_code, 'body': resp.text})

    return jsonify({'error': 'unknown operation'}), 400

@app.route('/api/v1/debug/env', methods=['GET'])
@verify_internal_caller
def debug_env():
    """Debug endpoint - returns filtered environment variables"""
    safe_keys = ['ECS_CLUSTER', 'AWS_REGION', 'SERVICE_NAME', 'MESH_NAMESPACE']
    env = {k: os.environ.get(k, '') for k in safe_keys}
    env['task_arn'] = get_task_metadata().get('TaskARN', 'unknown')
    return jsonify(env)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
